solution.solution.py:
def run(rules, tape):
    cells = list(tape)
    head = 0
    state = "start"
    while state != "halt":
        if head == len(cells):
            cells.append("_")
        rule = rules.get((state, cells[head]))
        if rule is None:
            break
        write, move, state = rule
        cells[head] = write
        if move == "R":
            head += 1
        elif move == "L":
            head -= 1
    return "".join(cells)

unitTests:
INVERT = {
    ("start", "0"): ("1", "R", "start"),
    ("start", "1"): ("0", "R", "start"),
    ("start", "_"): ("_", "S", "halt"),
}

# Adds one to a binary number written with its lowest bit first: 1101 is 1 + 0 + 4 + 8 = 11.
ADD_ONE = {
    ("start", "1"): ("0", "R", "start"),
    ("start", "0"): ("1", "S", "halt"),
    ("start", "_"): ("1", "S", "halt"),
}

@test("inverting bits")
def _():
    check_eq(run(INVERT, "1011_"), "0100_")
    check_eq(run(INVERT, "_"), "_")

@test("adding one, lowest bit first")
def _():
    check_eq(run(ADD_ONE, "1101"), "0011")
    check_eq(run(ADD_ONE, "0"), "1")
    check_eq(run(ADD_ONE, "111"), "0001")

@test("no rule stops the machine")
def _():
    check_eq(run({("start", "a"): ("b", "R", "start")}, "aax"), "bbx")

